from pathlib import Path
from html import escape
root=Path(__file__).resolve().parent.parent
S={
 'boe':'https://www.boe.ca.gov/prop19/', 'irs':'https://www.irs.gov/instructions/i706', 'basis':'https://www.irs.gov/businesses/small-businesses-self-employed/frequently-asked-questions-on-estate-taxes', 'rental':'https://www.irs.gov/publications/p527', 'home':'https://www.irs.gov/publications/p523', 'ftb':'https://www.ftb.ca.gov/forms/2025/2025-540-instructions.html', 'gains':'https://www.ftb.ca.gov/file/personal/income-types/capital-gains-and-losses.html', 'treasury':'https://www.treasurydirect.gov/marketable-securities/reinvesting-a-marketable-security/', 'history':'https://www.federalreservehistory.org/essays/great-depression', 'history2':'https://www.federalreservehistory.org/essays/great-recession-and-its-aftermath', 'sf':'https://www.sf.gov/information/sec-373-rent-limitations', 'measure':'https://media.api.sf.gov/documents/N26_EN_VIP.pdf', 'election':'https://www.sfelections.org/results/20261103/index.html', 'insurance':'https://www.insurance.ca.gov/0400-news/0100-press-releases/2018/release138-18.cfm', 'appraisal':'https://www.irs.gov/publications/p561', 'exchange':'https://www.irs.gov/instructions/i8824', 'extension':'https://www.irs.gov/instructions/i4768', 'gift':'https://www.irs.gov/pub/irs-pdf/p559.pdf', 'rates':'https://sccassessor.org/index.php/online-services/property-search/searching-records-buying-maps', 'transfer':'https://clerkrecorder.santaclaracounty.gov/recording-documents/recording-real-estate', 'year2027':'https://www.irs.gov/newsroom/irs-releases-tax-inflation-adjustments-for-tax-year-2027-taxpayers-continue-to-benefit-from-the-working-families-tax-cuts', 'cal':'https://www.ftb.ca.gov/about-ftb/data-reports-plans/summary-of-federal-income-tax-changes/index.html', 'calestate':'https://www.ftb.ca.gov/tax-pros/law/legislation/2017-2018/sb726-032317.pdf'
}
def link(k,label='Official source'):
 return f'<a href="{S[k]}" target="_blank" rel="noopener noreferrer">{label} ↗</a>'
def table(headers, rows):
 return '<div class="table-wrap"><table><thead><tr>'+''.join(f'<th scope="col">{escape(h)}</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{c}</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def card(kicker,title,body,href,label):
 return f'<a class="feature" href="{href}"><span class="eyebrow">{kicker}</span><h3>{title}</h3><p>{body}</p><span class="arrow">{label} →</span></a>'
def section(kicker,title,intro=''):
 return f'<div class="section-head"><div><span class="eyebrow">{kicker}</span><h2>{title}</h2></div><p>{intro}</p></div>'
nav=[('index.html','Overview'),('paths.html','Decision paths'),('questions.html','Open questions'),('timeline.html','Timeline'),('stress.html','Black swan lab'),('law.html','Tax & law'),('review.html','Flagged for review'),('brief.html','Adviser brief'),('suggestions.html','Suggestions'),('glossary.html','Glossary')]
navhtml=''.join(f'<a href="{url}">{name}</a>' for url,name in nav)
footer='<footer><div>PRIVATE BY DESIGN <span> / </span> Public educational guide · No household data stored</div><p>Not legal, tax, or investment advice. Rules and figures require verification at the actual transfer date.</p></footer>'
def page(title,desc,body):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{escape(desc)}"><title>{escape(title)} | Decision Atlas</title><link rel="stylesheet" href="assets/style.css"><script defer src="assets/app.js"></script></head><body><div class="layout"><aside class="sidebar"><a class="brand" href="index.html"><span class="brand-mark">✳</span><span>DECISION<br>ATLAS<small>PROPERTY PLANNING</small></span></a><div class="sidebar-label">THE WORKSPACE</div><nav aria-label="Main navigation">{navhtml}</nav><div class="sidebar-bottom"><span class="status-dot"></span> Research snapshot<br><strong>25 NOV 2026</strong></div></aside><main id="main"><div class="topbar"><span>DECISION WORKSPACE <span class="slash">/</span> {escape(title.upper())}</span><a href="brief.html">Adviser brief ↗</a></div>{body}{footer}</main></div></body></html>'''
def write(name,title,desc,body): (root/name).write_text(page(title,desc,body))
write('index.html','Overview','A privacy-first decision framework.', '''<div class="hero"><div><span class="eyebrow"><span class="status-dot"></span> A FRAMEWORK, NOT A FORECAST</span><h1>A clearer path<br>through <em>what’s next.</em></h1><p class="lead">A thoughtful starting point for a future property decision. Compare the tradeoffs, surface the unknowns, and bring better questions to your advisers.</p><div class="actions"><a class="button" href="questions.html">Start with the questions <span>↗</span></a><a class="text-link" href="paths.html">Explore the paths →</a></div></div><div class="hero-art" aria-hidden="true"><div class="orbit o1"></div><div class="orbit o2"></div><div class="orbit o3"></div><div class="art-core"><span>THE</span><strong>long<br>view.</strong><i>✳</i></div><span class="art-label al1">CLARITY</span><span class="art-label al2">CONTEXT</span><span class="art-label al3">CHOICE</span></div></div>
<div class="notice"><strong>Start here: what would change the answer?</strong><span>Actual rent and operating costs, the heir’s long-term residence, tax basis, estate liquidity and risk tolerance can each change the preferred path. No winner is supportable yet.</span></div>
''' + section('01 / THE DECISION','First, establish the facts.','One property may be inherited; a second is already owned. They are not the same transfer.') + '''<div class="fact-grid"><div><span class="number">01</span><h3>The inherited property</h3><p>Residence, rental, sale, or a sequence of these. The transfer can trigger a new property-tax assessment.</p></div><div><span class="number">02</span><h3>The existing property</h3><p>Already owned by the heir. Rental income and occupancy choices belong in every comparable path; inheritance alone does not transfer it.</p></div><div><span class="number">03</span><h3>The broader estate</h3><p>Its assets, liabilities, prior gifts and available cash—not just the property—determine estate-tax exposure.</p></div></div>''' + section('02 / EXPLORE','Make the uncertainty useful.','A practical sequence for getting from possibilities to a decision.') + '<div class="feature-grid">'+card('01 / COMPARE','Map the options','Compare immediate sale, occupancy, rental, and mixed paths at the same dates.','paths.html','View decision paths')+card('02 / INVESTIGATE','Find the missing pieces','A prioritized checklist of questions, evidence, and who can help.','questions.html','See open questions')+card('03 / STRESS TEST','Explore a rough landing','Test a synthetic stock crash and Treasury staging side by side.','stress.html','Open black swan lab')+card('04 / TAKE ACTION','Talk to your advisers','A concise, printable briefing sheet for your attorney and CPA.','brief.html','Open the brief')+'</div><div class="privacy-band"><span>✳</span><div><strong>Privacy is the starting point.</strong><p>No addresses, parcel identifiers, household values, leases, or account information are published here. Rounded figures can still identify a household. Keep a detailed inventory offline and share it only through a secure channel.</p></div><a href="review.html">Review limitations →</a></div>')
rows=[('Sell in the transfer year','Keep the existing home as-is; compare net sale proceeds and a defined portfolio policy.','Near-term sale may limit post-death appreciation but selling costs, tax basis, estate claims and timing matter.','basis'),('Live long term','Move into the inherited home and explicitly model the existing home’s occupancy and legal rental income.','Test eligibility for the parent-child property-tax exclusion; compare imputed rent, both homes’ costs and liquidity.','boe'),('Rent long term','Keep existing occupancy; let the inherited home at independently estimated market rent.','Reassessment, vacancy, insurance, management, depreciation and repairs can materially change returns.','rental'),('Live, then sell','Occupy first, then sell at a common future comparison date.','Apply the home-sale exclusion only if tests are met; model reassessment when qualifying occupancy ends.','home'),('Rent, then sell','Rent initially and sell at the same future horizon.','Model depreciation allowed or allowable and tax on disposition; ask about 1031 before a sale.','exchange'),('Sell and stage investment','Park net proceeds in short Treasury securities for 24–36 months; then phase into stocks.','Crash-entry protection is not guaranteed; missed recovery, inflation and falling reinvestment yields are real risks.','treasury')]
write('paths.html','Decision paths','Compare pure and mixed paths.', '<div class="page-head"><span class="eyebrow">THE DECISION / 01</span><h1>Different paths.<br><em>One fair comparison.</em></h1><p>Establish decision rules before looking at projections. Until inputs are verified, this is a comparison framework—not a recommendation.</p></div>'+table(['Path','What to compare','Decision-sensitive detail','Source'],[(a,b,c,link(d)) for a,b,c,d in rows])+'''<div class="two-col"><div class="panel"><span class="eyebrow">THE FAIR-COMPARISON RULE</span><h2>Same clock, same household.</h2><p>Use identical transfer dates, horizons and inflation assumptions for every path. Include both properties, debt and payoff, taxes, insurance, utilities, capital work, vacancy, transactions, liquid reserves, investment contributions and imputed rent. Count housing benefits once.</p><p>For living then selling, assess the actual two-of-five-year ownership and use tests, previous exclusions and rental-use rules—not an automatic switch. '''+link('home')+'''</p></div><div class="panel pale"><span class="eyebrow">WRITE THIS DOWN FIRST</span><h2>Precommit to the rules.</h2><p>Choose minimum liquid reserves, maximum acceptable downside, time willing to live in the home, landlord workload, risk limits and the minimum advantage required to justify a change. Record the decision, date and rationale privately. Revisit annually.</p><a class="text-link" href="brief.html">Bring this to your advisers →</a></div></div>''')
q=[('Eligibility & trust','Who inherits, when, and under which trust terms? Was the inherited property the transferor’s principal residence?','Trustee and attorney: review trust, title, occupancy and authority. Do not publish documents.','boe'),('Independent valuation','What are the date-of-death value, land/building allocation and credible rent?','Obtain a written appraisal and multiple local rental comparables. Voucher schedules are not a market appraisal.','appraisal'),('Taxes & assessment','What are the parcel’s tax-rate area, local rates, fixed charges, adjusted base and eligibility?','Privately consult the assessor and current tax bill; do not infer a parcel rate from a ZIP code.','rates'),('Estate exposure','What is the full estate, adjusted taxable gifts, marital status, DSUE and cash available for taxes?','Create a secure inventory with the attorney and CPA. Determine filing, portability and liquidity needs.','irs'),('Existing property','What are each lease, permitted unit status, occupancy rights and lawful rents?','Attorney checks leases, rent and eviction rules; preserve actual operating history and verify occupancy.','sf'),('Operating costs','What are policy premiums, utility statements, solar credits, maintenance and repair needs?','Get insurance quotes for the correct occupancy and coverage; inspect both buildings and prepare five-year work plans.','insurance'),('Basis & disposition','What is the tax basis and adjusted rental basis; is an exchange or home-sale exclusion possible?','Obtain allocation and depreciation records. Discuss exchange eligibility and intermediary before contracting to sell.','exchange'),('Portfolio policy','What reserves and downside can the household tolerate; what asset mix and tax budget apply?','Write a policy for staging, rebalancing, spending, reinvestment and review before funds arrive.','treasury')]
write('questions.html','Open questions','What we know, what we do not and how to find it.', '<div class="page-head"><span class="eyebrow">DUE DILIGENCE / 02</span><h1>The questions<br><em>before the answer.</em></h1><p>Known: one home is expected to transfer, while the other is already owned. Everything property-specific below remains private and unverified here.</p></div>'+table(['Question','What must be established','How to find out','Source'],[(a,'Not verified in this public guide.',b+' '+c,link(d)) for a,b,c,d in q])+'''<div class="notice"><strong>Do not reverse-engineer the choice.</strong><span>Before valuation arrives, write down what conditions would make each path acceptable. Record the decision and date in the private planning file—not this public site.</span></div>''')
steps=[('Now','Secure trust, estate inventory, prior gift records and a dated decision policy; obtain independent insurance, property and rental estimates.','appraisal'),('At death / transfer','Trustee confirms authority, secures assets, obtains written date-of-death appraisal and identifies creditors, cash needs and the change-in-ownership date.','basis'),('Within 9 months','If required, generally file Form 706 and pay estate tax. A filing extension is not automatically an extension to pay; ask about portability.','extension'),('Within 1 year','For eligible family-home relief, claim the homeowners’ or disabled veterans’ exemption and establish qualifying occupancy; confirm exact deadlines with the assessor.','boe'),('Within 3 years or before transfer','Generally claim the parent-child exclusion by the earlier of these dates for timely relief; special late-claim rules may apply.','boe'),('Before a sale','Compare sale in the transfer tax year with other paths; obtain basis, selling costs and professional advice on any like-kind exchange before closing.','exchange'),('Every year','Refresh law, rents, insurance, valuations, reserves and shock scenarios; rebuild the private model and record whether the recommendation changed.','boe')]
write('timeline.html','Timeline','Inheritance workflow and deadlines.', '<div class="page-head"><span class="eyebrow">THE PROCESS / 03</span><h1>A timeline for<br><em>the long view.</em></h1><p>Relative deadlines are guides, not automatic calendar dates. Counsel should determine the legally relevant transfer date and all filing requirements.</p></div><div class="timeline">'+''.join(f'<div class="event"><div class="event-date">{a}</div><div class="event-content"><p>{b}</p>{link(c)}</div></div>' for a,b,c in steps)+'</div>')
law=[('Property tax ≠ income basis','An eligible family-home transfer may preserve some assessment; income-tax basis is a separate calculation. Claim relief only where the eligibility and occupancy requirements are met.','boe'),('Prop 19 allowance','The official allowance is $1,044,586 for transfers from February 16, 2025 through February 15, 2027, added to the factored base-year value. It is adjusted every two years; 2040–2050 amounts are unknown.','boe'),('Estate exclusion','Federal basic exclusion: $15,000,000 for 2026 and $15,480,000 for 2027. These are per decedent basic amounts, not a tax-free amount per heir. Prior gifts, DSUE and deductions matter.','year2027'),('California estate tax','The Franchise Tax Board’s 2017 legislative analysis described California’s state estate pick-up tax as zero after the federal credit was repealed. Verify current law and any out-of-state exposure with counsel.','calestate'),('Basis at death','Inherited-property basis is generally date-of-death fair market value, subject to exceptions, title and estate elections. A prompt sale can still produce gain or loss and transaction costs.','basis'),('California gain sensitivity','California taxes capital gains as ordinary income. For an individual resident, 2025 Form 540 line 62 applies an additional 1% to taxable income above $1 million—not all gain and not all income. Marginal rate and other taxes depend on facts.','ftb'),('Rental depreciation','Residential rental buildings generally use a 27.5-year GDS recovery period; land is not depreciable. Conversion, mixed use, placed-in-service dates and allowed/allowable depreciation require CPA review.','rental'),('Home-sale exclusion','Generally requires two years of ownership and use in the five years before sale, with exceptions and limits; depreciation and nonqualified use can reduce relief.','home'),('SF Proposition H, 2026','Official preliminary results show approval leading; certification must be rechecked. The ballot describes a 2027–2042 Muni parcel tax, with inflation adjustments and eligibility-specific reductions. The building’s tax cannot be determined without classification, area and exemption facts.','election')]
write('law.html','Tax & law','Official sources and legal distinctions.', '<div class="page-head"><span class="eyebrow">RESEARCH / 04</span><h1>Know which rule<br><em>does what.</em></h1><p>Snapshot: 25 November 2026. Laws and proposals may change before the transfer. Verify current authority with counsel annually and again at the decision date.</p></div>'+table(['Topic','What the official source says','Source'],[(a,b,link(c)) for a,b,c in law])+'''<div class="panel"><h2>Assessment and transaction details</h2><p>For a qualifying transfer, the general assessment calculation starts with the existing factored base-year value; if market value exceeds that base plus the applicable allowance, the excess is added to the base. Subsequent inflation adjustments and continued eligibility must be checked; a move-out may cause reassessment. The transfer-year allowance is not the income-tax basis. '+link('boe')+'</p><p>Santa Clara County’s recorder describes a documentary transfer tax of $0.55 per $500 or fraction of value, subject to exemptions and details; recording fees depend on documents. Obtain a closing quote and do not infer a transaction-specific cost. '+link('transfer')+'</p></div><div class="panel"><h2>Proposition H: terms and status</h2><p>The official voter text describes a multifamily base of $249 in the first year, plus $0.195 per square foot above 5,000 square feet, capped at $50,000, with adjustments and possible owner-occupied senior deductions. These statutory figures are not personal data; use full statutory precision, not rounded legal rates. Applicability, eligible building area, senior eligibility and certification are unverified. '''+link('measure','Official voter pamphlet')+' · '+link('election','Preliminary election results')+'''</p><p>Legislation described as proposed should not be treated as enacted. Monitor official legislature and elections records; this static site cannot monitor or update itself.</p></div>''')
write('stress.html','Black swan lab','A synthetic investment stress test.', '''<div class="page-head"><span class="eyebrow">SCENARIO LAB / 05</span><h1>What if the market<br><em>doesn’t cooperate?</em></h1><p>Test sequencing, not prediction. These are deliberately synthetic scenarios inspired by historic downturns, not historical return series or a personalized forecast.</p></div><div class="notice"><strong>Staging trades one risk for another.</strong><span>Short Treasuries may reduce early equity exposure, but yields can fall at reinvestment, inflation can erode purchasing power, and a rebound can be missed. Selling before maturity can realize losses. <a href="https://www.treasurydirect.gov/marketable-securities/reinvesting-a-marketable-security/">TreasuryDirect ↗</a></span></div><div class="lab"><div class="lab-controls"><span class="eyebrow">ILLUSTRATIVE ASSUMPTIONS</span><h2>Adjust the scenario.</h2><label for="scenario">Sequence</label><select id="scenario"><option value="depression">Depression-like: prolonged decline</option><option value="recession">Recession-like: sharp shock, rebound</option><option value="steady">Steady: no initial shock</option></select><label for="delay">Treasury holding period</label><select id="delay"><option value="24">24 months</option><option value="36">36 months</option></select><label for="yield">Treasury annual yield (%)</label><input type="number" id="yield" value="3" min="0" max="15" step="0.5"><label for="inflation">Annual inflation (%)</label><input type="number" id="inflation" value="3" min="0" max="15" step="0.5"><label for="horizon">Horizon</label><select id="horizon"><option value="10">10 years</option><option value="20">20 years</option><option value="50">50 years</option></select><button id="run" class="button" type="button">Recalculate →</button><p class="small">No data is saved or sent. Values are index points, not dollars.</p></div><div class="lab-results"><div class="lab-title"><div><span class="eyebrow">COMPARING $100 OF PROCEEDS</span><h2>Same start. Different entry.</h2></div><span class="pill">ILLUSTRATIVE</span></div><p>Real purchasing power, indexed to 100 at transfer. Monthly compounding. Stocks enter immediately or after the selected Treasury holding period, then in equal monthly fractions over 36 months.</p><div id="chart" role="img" aria-label="Illustrative investment value chart"></div><div class="legend"><span><i class="legend-a"></i> Immediate stocks</span><span><i class="legend-b"></i> Treasury then phased stocks</span></div><div id="summary" aria-live="polite"></div><div id="projection"></div></div></div><div class="panel"><h2>What this does—and does not—show</h2><p>The hypothetical annual stock returns are: depression-like −25%, −35%, −20%, 15%, 10%, then 6%; recession-like −35%, 25%, 15%, then 6%; steady 6%. The model repeats each annual return monthly and holds the selected Treasury yield constant. Future rates are unknown. No taxes, fees, coupons, sale costs, estate cash, other assets or property cash flows are included. A proper reinvestment-rate sensitivity must separately vary future auction rates. No percentile or probability is implied.</p><p>Historic context: '''+link('history','Federal Reserve: Great Depression')+' · '+link('history2','Federal Reserve: Great Recession')+'''</p><p>These invented returns do not reproduce 1929 or 2008. Obtain authoritative total-return, bill-yield and inflation data with aligned dates before a historical backtest. This toy cannot rank the property paths.</p></div>''')
review=[('Public privacy','Rounded personal property figures remain linkable. No identifying values, precise dates, addresses or parcel IDs are published. A public site cannot host the private inventory.','insurance'),('Property tax rate area','Not established. A ZIP code does not identify the tax-rate area. Obtain the assessor’s records privately.','rates'),('Valuation & rent','No independently verified appraisal or comparable rent; rental economics and best path cannot be ranked.','appraisal'),('Insurance & utilities','No property-specific official insurance quote or verified utility bills; obtain occupancy-specific coverage quotes and bills privately.','insurance'),('Debt & estate liquidity','Unknown balances, terms, estate inventory, gifts and marital elections prevent a reliable estate-tax calculation.','irs'),('2026 Proposition H','Preliminary election results are not certification. Actual classification, square footage and exemption are unknown; no property-specific tax has been calculated.','election'),('Historical stress test','The lab uses fictional return sequences. Historical 1929/2008 data, distribution, full tax-aware property model and reinvestment-rate paths are not validated or implemented.','history'),('Transfer tax & recording','Current jurisdiction-specific transfer tax and recording costs have not been established; obtain a written closing estimate.','transfer'),('Future law','Transfer in a future decade is uncertain. No automatic official-source updates or 2040–2050 law prediction.','boe')]
write('review.html','Flagged for review','Unverified information and limitations.', '<div class="page-head"><span class="eyebrow">TRANSPARENCY / 06</span><h1>What remains<br><em>unverified.</em></h1><p>Unknown does not mean zero. These items are intentionally blank in any decision calculation. Flagging a gap is not verification.</p></div>'+table(['Item','Status & next action','Official starting point'],[(a,b,link(c)) for a,b,c in review])+'''<div class="panel"><h2>Contain exposure</h2><p>The available repository history was inspected: its initial commit contained only the README. No pre-rounding property dataset was found in this checkout. This does not establish that no other public copies, forks, caches, search indexes, or prior repositories exist. If material was exposed elsewhere, privately identify copies, contact owners, revoke any compromised credentials, request removal and follow applicable legal advice. Git history rewriting alone cannot erase copies.</p></div>''')
write('suggestions.html','Suggestions','A review queue of improvements.', '<div class="page-head"><span class="eyebrow">REVIEW QUEUE / 07</span><h1>Ideas to consider.<br><em>Not assumptions to adopt.</em></h1><p>Choose and document priorities before implementation. These are suggestions, not decisions or claims of completed work.</p></div>'+table(['Priority','Suggestion','Why it matters','Source'],[(a,b,c,link(d)) for a,b,c,d in [('01','Build a separate offline model with ranges and tests','Compare all pathways after taxes, occupancy, debt, maintenance and liquidity; never commit private inputs.','rental'),('02','Obtain local appraisals and multiple rent comparables','Unverified rental revenue can reverse the result.','appraisal'),('03','Build five-year capital plans','Inspect roof, systems, structure, seismic and deferred work; budget both properties privately.','insurance'),('04','Validate policy and extreme scenarios annually','Revisit crash sequence, reserve minimum, inflation and rate-reinvestment risk.','treasury'),('05','Add verified historical and distribution data','A synthetic chart is not a historical backtest or a statistical distribution. Source and validate data before use.','history'),('06','Establish an official-law review cadence','Record change, status, effective date, source and adviser decision each year.','boe')]])+'''<div class="notice"><strong>Decision log template</strong><span>Decision: [private] · Date: [private] · Evidence: [private] · Why: [private] · Revisit: [private]. Keep this off the public site.</span></div>''')
write('brief.html','Adviser brief','One-page attorney and CPA briefing sheet.', '''<div class="brief-actions"><span class="eyebrow">READY FOR A CONVERSATION</span><button class="button" type="button" onclick="window.print()">Print / save PDF ↗</button></div><article class="brief"><header><div><span class="eyebrow">DECISION ATLAS / PRIVATE DISCUSSION</span><h1>Attorney &amp; CPA<br><em>briefing sheet.</em></h1><p>General framework · Research snapshot: 25 November 2026</p></div><span class="brief-symbol">✳</span></header><div class="brief-grid"><section><h2>01 / Situation</h2><p>One home is expected to transfer through a trust in a future decade. A second home is already owned by the heir and has rental occupancy. Evaluate both together; do not assume both are inherited.</p></section><section><h2>02 / Decision</h2><p>Compare same-year sale, living, rental, living then sale, renting then sale, and sale with a Treasury-to-stock phase. Agree decision thresholds before receiving projections.</p></section><section><h2>03 / Property &amp; income tax</h2><p>Confirm ownership and trust terms, date-of-death valuation, basis, assessment and Prop 19 eligibility/deadlines. Check rental depreciation, 121 eligibility, selling expenses and whether 1031 is viable before selling.</p></section><section><h2>04 / Estate &amp; liquidity</h2><p>Inventory all assets and liabilities privately; review prior taxable gifts, portability and estate filing/payment. Determine cash needed, funding sources and a reserve. Federal basic exclusion differs by year.</p></section><section><h2>05 / Missing evidence</h2><p>Obtain independent property and rent estimates; bills, tax-rate area, insurance quotes, debt, leases, occupancy, capital plan and solar history. Do not treat unknowns as zero.</p></section><section><h2>06 / Investment policy</h2><p>Set asset allocation, reserves, time horizon, acceptable loss and rebalancing. Compare immediate investment to staging; weigh reinvestment and missed-rebound risk alongside crash protection.</p></section></div><div class="brief-bottom"><strong>Decisions to document privately:</strong> chosen path / date / assumptions / rationale / review date. Bring records securely; do not paste them into a public website.<br>Sources: '''+link('boe','BOE')+' · '+link('irs','IRS Form 706')+' · '+link('home','IRS home sale')+' · '+link('rental','IRS rental property')+' · '+link('ftb','FTB Form 540')+'''</div></article>''')
write('glossary.html','Glossary','Definitions for this decision.', '<div class="page-head"><span class="eyebrow">REFERENCE / 08</span><h1>A little less jargon.<br><em>A lot more clarity.</em></h1><p>Terms that sound similar can have very different consequences. Ask your advisers how they apply to your circumstances.</p></div>'+table(['Term','Plain-language meaning','Source'],[(a,b,link(c)) for a,b,c in [('Factored base-year value','The property-tax base after applicable annual inflation adjustments; not the same as market value.','boe'),('Income-tax basis','The starting value used to calculate taxable gain or loss; adjustments can apply.','basis'),('Estate exclusion','The basic federal amount used in calculating the estate and gift tax credit, not a per-beneficiary inheritance allowance.','irs'),('Portability / DSUE','An election can transfer a deceased spouse’s unused exclusion to a surviving spouse, subject to requirements.','irs'),('Imputed rent','The hypothetical housing value of living in an owned home; not cash income. Avoid counting it twice.','home'),('Depreciation','A tax deduction for eligible property over time; it generally reduces adjusted basis.','rental'),('Reinvestment risk','The risk that maturing securities must be reinvested at less favorable rates.','treasury'),('Like-kind exchange','A qualifying exchange of investment or business real property may defer gain; personal-use property is not automatically eligible.','exchange')]]))
print('Built',len(nav),'pages')
